-- >>> src/40_cross_schema_and_common.sql
-- =============================================================================
-- 40  CROSS-SCHEMA FOREIGN KEYS AND UNIFORM COMMON-COLUMN ENFORCEMENT
-- -----------------------------------------------------------------------------
-- Tenant tables were created before Identity tables; their Identity
-- references are added here (bootstrap order: tenant -> organization ->
-- principal; the tenant master never needs an Identity FK).
-- =============================================================================
--
ALTER TABLE cob3_tenant.tenant_contacts
    ADD CONSTRAINT tenant_contacts_principal_fk FOREIGN KEY (tenant_id, principal_id)
        REFERENCES cob3_identity.principals (tenant_id, principal_id) ON UPDATE RESTRICT ON DELETE RESTRICT;
--
ALTER TABLE cob3_tenant.subscription_changes
    ADD CONSTRAINT subscription_changes_requested_by_fk FOREIGN KEY (tenant_id, requested_by_principal_id)
        REFERENCES cob3_identity.principals (tenant_id, principal_id) ON UPDATE RESTRICT ON DELETE RESTRICT,
    ADD CONSTRAINT subscription_changes_approved_by_fk FOREIGN KEY (tenant_id, approved_by_principal_id)
        REFERENCES cob3_identity.principals (tenant_id, principal_id) ON UPDATE RESTRICT ON DELETE RESTRICT;
--
ALTER TABLE cob3_tenant.organization_quota_allocations
    ADD CONSTRAINT organization_quota_allocations_organization_fk FOREIGN KEY (tenant_id, organization_id)
        REFERENCES cob3_identity.organizations (tenant_id, organization_id) ON UPDATE RESTRICT ON DELETE RESTRICT;
--
ALTER TABLE cob3_tenant.usage_events
    ADD CONSTRAINT usage_events_organization_fk FOREIGN KEY (tenant_id, organization_id)
        REFERENCES cob3_identity.organizations (tenant_id, organization_id) ON UPDATE RESTRICT ON DELETE RESTRICT;
--
ALTER TABLE cob3_tenant.usage_rollups
    ADD CONSTRAINT usage_rollups_organization_fk FOREIGN KEY (tenant_id, organization_id)
        REFERENCES cob3_identity.organizations (tenant_id, organization_id) ON UPDATE RESTRICT ON DELETE RESTRICT;
--
ALTER TABLE cob3_tenant.quota_counters
    ADD CONSTRAINT quota_counters_organization_fk FOREIGN KEY (tenant_id, organization_id)
        REFERENCES cob3_identity.organizations (tenant_id, organization_id) ON UPDATE RESTRICT ON DELETE RESTRICT;
--
-- ---------------------------------------------------------------------------
-- Uniform common-column rules for all 48 logical tables:
--   <table>_metadata_object_ck        jsonb_typeof(metadata) = 'object'
--   <table>_metadata_no_secrets_ck    heuristic: no top-level secret-named keys
--   <table>_row_version_positive_ck   row_version > 0
--   <table>_created_by_actor_ck       principal:<uuid> | system:<name>
--   <table>_updated_by_actor_ck       principal:<uuid> | system:<name>
--   trg_90_stamp_row                  trusted timestamp/actor/version stamping
--   trg_00_block_truncate             no TRUNCATE (retention is controlled)
-- ---------------------------------------------------------------------------
FOREACH _i_table IN ARRAY _i_logical_tables LOOP
    _i_schema := pg_catalog.split_part(_i_table, '.', 1);
    _i_name   := pg_catalog.split_part(_i_table, '.', 2);
    EXECUTE pg_catalog.format(
        'ALTER TABLE %1$I.%2$I'
        ' ADD CONSTRAINT %3$I CHECK (jsonb_typeof(metadata) = ''object''),'
        ' ADD CONSTRAINT %4$I CHECK (NOT (metadata ?| ARRAY[''password'', ''secret'', ''client_secret'', ''private_key'', ''api_key'', ''access_token'', ''refresh_token'', ''token''])),'
        ' ADD CONSTRAINT %5$I CHECK (row_version > 0),'
        ' ADD CONSTRAINT %6$I CHECK (created_by ~ %8$L),'
        ' ADD CONSTRAINT %7$I CHECK (updated_by ~ %8$L)',
        _i_schema, _i_name,
        _i_name || '_metadata_object_ck',
        _i_name || '_metadata_no_secrets_ck',
        _i_name || '_row_version_positive_ck',
        _i_name || '_created_by_actor_ck',
        _i_name || '_updated_by_actor_ck',
        '^(principal:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}|system:[a-z0-9][a-z0-9_.:-]{0,200})$');
    EXECUTE pg_catalog.format(
        'CREATE TRIGGER trg_90_stamp_row BEFORE INSERT OR UPDATE ON %I.%I FOR EACH ROW EXECUTE FUNCTION cob3_identity.tg_stamp_row()',
        _i_schema, _i_name);
END LOOP;
--
FOREACH _i_table IN ARRAY (_i_logical_tables || _i_support_tables) LOOP
    EXECUTE pg_catalog.format(
        'CREATE TRIGGER trg_00_block_truncate BEFORE TRUNCATE ON %I.%I FOR EACH STATEMENT EXECUTE FUNCTION cob3_identity.tg_block_truncate()',
        pg_catalog.split_part(_i_table, '.', 1), pg_catalog.split_part(_i_table, '.', 2));
END LOOP;
--
-- Append-only tables: no UPDATE or DELETE by anyone (including the owner,
-- unless a reviewed retention migration explicitly disables the trigger).
CREATE TRIGGER trg_05_append_only BEFORE UPDATE OR DELETE ON cob3_tenant.tenant_lifecycle_events
    FOR EACH ROW EXECUTE FUNCTION cob3_identity.tg_append_only();
CREATE TRIGGER trg_05_append_only BEFORE UPDATE OR DELETE ON cob3_tenant.usage_events
    FOR EACH ROW EXECUTE FUNCTION cob3_identity.tg_append_only();
CREATE TRIGGER trg_05_append_only BEFORE UPDATE OR DELETE ON cob3_identity.audit_events
    FOR EACH ROW EXECUTE FUNCTION cob3_identity.tg_append_only();
CREATE TRIGGER trg_05_append_only BEFORE UPDATE OR DELETE ON cob3_identity.credential_permission_bindings
    FOR EACH ROW EXECUTE FUNCTION cob3_identity.tg_append_only();
CREATE TRIGGER trg_05_append_only BEFORE UPDATE OR DELETE ON cob3_tenant.foundation_installations
    FOR EACH ROW EXECUTE FUNCTION cob3_identity.tg_append_only();
--
-- >>> src/50_authorization_core.sql
-- =============================================================================
-- 50  AUTHORIZATION CORE
-- -----------------------------------------------------------------------------
-- * Catalog fail-closed guards (replaced only by the separately invoked
--   Catalog integration; never by an always-true validator).
-- * Eligibility, live RBAC, tenant-control RBAC.
-- * evaluate_access: the single decision function implementing
--     interactive human sessions  -> current RBAC
--     credential / noninteractive -> live grantor RBAC AND live grantee RBAC
--                                    AND approved grant entry AND credential
--                                    subset (when present) AND lifecycle,
--                                    organization, scope, usage and expiry checks.
-- * ctx_* predicates used by RLS policies (evaluate once per statement via
--   scalar sub-selects in the policies).
-- All functions here are read-only. SECURITY DEFINER functions run as
-- cob3_owner with a pinned search_path and fully qualified references.
-- =============================================================================
--
-- ---------------------------------------------------------------------------
-- Catalog guards (pending integration)
-- ---------------------------------------------------------------------------
CREATE FUNCTION cob3_identity.catalog_integration_installed()
    RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path = pg_catalog, pg_temp
AS $fn$ SELECT false $fn$;
--
CREATE FUNCTION cob3_identity.assert_catalog_domain(p_tenant_id uuid, p_organization_id uuid, p_domain_id uuid)
    RETURNS void
    LANGUAGE plpgsql STABLE
    SET search_path = pg_catalog, pg_temp
AS $fn$
BEGIN
    RAISE EXCEPTION USING ERRCODE = 'SKCAT',
        MESSAGE = pg_catalog.format('Catalog integration is not installed: domain %s cannot be validated for organization %s and is rejected (fail closed).', p_domain_id, p_organization_id),
        HINT = 'Domain-scoped access and team-domain responsibility become available only after the separately invoked Catalog integration verifies cob3_catalog and installs real foreign keys.';
END
$fn$;
--
CREATE FUNCTION cob3_identity.assert_catalog_asset(p_tenant_id uuid, p_organization_id uuid, p_asset_id uuid)
    RETURNS void
    LANGUAGE plpgsql STABLE
    SET search_path = pg_catalog, pg_temp
AS $fn$
BEGIN
    RAISE EXCEPTION USING ERRCODE = 'SKCAT',
        MESSAGE = pg_catalog.format('Catalog integration is not installed: asset %s cannot be validated for organization %s and is rejected (fail closed).', p_asset_id, p_organization_id),
        HINT = 'Asset-scoped access becomes available only after the separately invoked Catalog integration.';
END
$fn$;
--
-- Resource resolution for any target that is not the organization entity
-- itself. Until a trusted Catalog resolver is installed this denies.
CREATE FUNCTION cob3_identity.catalog_scope_covers(
        p_tenant_id uuid, p_organization_id uuid, p_scope_type text, p_domain_id uuid, p_asset_id uuid,
        p_include_contained_assets boolean, p_team_id uuid, p_resource_type text,
        p_target_type text, p_target_id uuid, p_at timestamptz)
    RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path = pg_catalog, pg_temp
AS $fn$ SELECT false $fn$;
--
-- ---------------------------------------------------------------------------
-- Eligibility helpers
-- ---------------------------------------------------------------------------
CREATE FUNCTION cob3_identity.tenant_is_active(p_tenant_id uuid)
    RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path = pg_catalog, pg_temp
AS $fn$
    SELECT EXISTS (SELECT 1 FROM cob3_tenant.tenants t WHERE t.tenant_id = p_tenant_id AND t.status = 'active')
$fn$;
--
CREATE FUNCTION cob3_identity.principal_is_eligible(p_tenant_id uuid, p_principal_id uuid, p_at timestamptz)
    RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path = pg_catalog, pg_temp
AS $fn$
    SELECT EXISTS (
        SELECT 1
          FROM cob3_identity.principals p
         WHERE p.tenant_id = p_tenant_id
           AND p.principal_id = p_principal_id
           AND p.status = 'active'
           AND CASE p.principal_type
                 WHEN 'human' THEN EXISTS (
                     SELECT 1 FROM cob3_identity.user_profiles u
                      WHERE u.tenant_id = p.tenant_id AND u.principal_id = p.principal_id)
                 WHEN 'service_account' THEN EXISTS (
                     SELECT 1 FROM cob3_identity.service_accounts s
                      WHERE s.tenant_id = p.tenant_id AND s.principal_id = p.principal_id
                        AND (s.expires_at IS NULL OR s.expires_at > p_at))
                 WHEN 'automation' THEN EXISTS (
                     SELECT 1 FROM cob3_identity.automation_profiles a
                      WHERE a.tenant_id = p.tenant_id AND a.principal_id = p.principal_id
                        AND (a.expires_at IS NULL OR a.expires_at > p_at))
                 ELSE false
               END)
$fn$;
--
CREATE FUNCTION cob3_identity.membership_is_effective(p_tenant_id uuid, p_organization_id uuid, p_principal_id uuid, p_at timestamptz)
    RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path = pg_catalog, pg_temp
AS $fn$
    SELECT EXISTS (
        SELECT 1
          FROM cob3_identity.organization_memberships m
          JOIN cob3_identity.organizations o
            ON o.tenant_id = m.tenant_id AND o.organization_id = m.organization_id
         WHERE m.tenant_id = p_tenant_id
           AND m.organization_id = p_organization_id
           AND m.principal_id = p_principal_id
           AND m.status = 'active'
           AND o.status = 'active'
           AND m.valid_from <= p_at
           AND (m.valid_until IS NULL OR m.valid_until > p_at))
$fn$;
--
CREATE FUNCTION cob3_identity.grant_is_effective(p_tenant_id uuid, p_organization_id uuid, p_grant_id uuid, p_grantee_id uuid, p_at timestamptz)
    RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path = pg_catalog, pg_temp
AS $fn$
    SELECT EXISTS (
        SELECT 1
          FROM cob3_identity.authorization_grants g
         WHERE g.tenant_id = p_tenant_id
           AND g.organization_id = p_organization_id
           AND g.authorization_grant_id = p_grant_id
           AND g.grantee_principal_id = p_grantee_id
           AND g.status = 'active'
           AND g.valid_from <= p_at
           AND g.valid_until > p_at)
$fn$;
--
CREATE FUNCTION cob3_identity.session_is_valid(p_tenant_id uuid, p_session_id uuid, p_at timestamptz)
    RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path = pg_catalog, pg_temp
AS $fn$
    SELECT EXISTS (
        SELECT 1
          FROM cob3_identity.auth_sessions s
          JOIN cob3_identity.principals p
            ON p.tenant_id = s.tenant_id AND p.principal_id = s.principal_id
         WHERE s.tenant_id = p_tenant_id
           AND s.session_id = p_session_id
           AND s.revoked_at IS NULL
           AND s.authenticated_at <= p_at
           AND s.expires_at > p_at
           AND s.auth_version_at_issue = p.auth_version
           AND (s.external_identity_id IS NULL OR EXISTS (
                SELECT 1
                  FROM cob3_identity.external_identities e
                  JOIN cob3_identity.identity_providers ip
                    ON ip.tenant_id = e.tenant_id AND ip.identity_provider_id = e.identity_provider_id
                 WHERE e.tenant_id = s.tenant_id
                   AND e.external_identity_id = s.external_identity_id
                   AND e.status = 'active'
                   AND ip.status = 'active')))
$fn$;
--
-- Identity-administered resource types are authorized at organization scope
-- with the organization itself as the target. Every other resource type is a
-- Catalog/product resource and needs the Catalog resolver.
CREATE FUNCTION cob3_identity.is_org_administered_resource(p_resource_type text)
    RETURNS boolean
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    SET search_path = pg_catalog, pg_temp
AS $fn$
    SELECT p_resource_type IN ('organization', 'team', 'role', 'service_account', 'automation',
                               'grant', 'credential', 'action', 'audit')
$fn$;
--
CREATE FUNCTION cob3_identity.scope_covers_target(
        p_tenant_id uuid, p_organization_id uuid, p_scope_id uuid, p_team_id uuid,
        p_resource_type text, p_target_type text, p_target_id uuid, p_at timestamptz)
    RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path = pg_catalog, pg_temp
AS $fn$
    SELECT COALESCE((
        SELECT CASE
                 WHEN s.status <> 'active' THEN false
                 WHEN s.scope_type = 'organization'
                      AND p_target_type = 'organization'
                      AND p_target_id = s.organization_id
                      AND cob3_identity.is_org_administered_resource(p_resource_type) THEN true
                 ELSE cob3_identity.catalog_scope_covers(
                          s.tenant_id, s.organization_id, s.scope_type, s.domain_id, s.asset_id,
                          s.include_contained_assets, p_team_id, p_resource_type, p_target_type, p_target_id, p_at)
               END
          FROM cob3_identity.access_scopes s
         WHERE s.tenant_id = p_tenant_id
           AND s.organization_id = p_organization_id
           AND s.scope_id = p_scope_id), false)
$fn$;
--
-- Effective teams: active team, active current membership, and at least one
-- active current source (manual, or external group whose mapping, group and
-- provider are all active). Group freshness SLA is a backend/Settings policy.
CREATE FUNCTION cob3_identity.effective_team_ids(p_tenant_id uuid, p_organization_id uuid, p_principal_id uuid, p_at timestamptz)
    RETURNS SETOF uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path = pg_catalog, pg_temp
AS $fn$
    SELECT tm.team_id
      FROM cob3_identity.team_memberships tm
      JOIN cob3_identity.teams t
        ON t.tenant_id = tm.tenant_id AND t.organization_id = tm.organization_id AND t.team_id = tm.team_id
     WHERE tm.tenant_id = p_tenant_id
       AND tm.organization_id = p_organization_id
       AND tm.principal_id = p_principal_id
       AND tm.status = 'active'
       AND t.status = 'active'
       AND tm.valid_from <= p_at
       AND (tm.valid_until IS NULL OR tm.valid_until > p_at)
       AND EXISTS (
           SELECT 1
             FROM cob3_identity.team_membership_sources src
             LEFT JOIN cob3_identity.group_team_mappings g
               ON g.tenant_id = src.tenant_id AND g.organization_id = src.organization_id
              AND g.group_team_mapping_id = src.group_team_mapping_id
             LEFT JOIN cob3_identity.external_groups eg
               ON eg.tenant_id = g.tenant_id AND eg.external_group_id = g.external_group_id
             LEFT JOIN cob3_identity.identity_providers ip
               ON ip.tenant_id = eg.tenant_id AND ip.identity_provider_id = eg.identity_provider_id
            WHERE src.tenant_id = tm.tenant_id
              AND src.organization_id = tm.organization_id
              AND src.team_membership_id = tm.team_membership_id
              AND src.status = 'active'
              AND src.valid_from <= p_at
              AND (src.valid_until IS NULL OR src.valid_until > p_at)
              AND (src.source_type = 'manual'
                   OR (g.status = 'active' AND eg.status = 'active' AND ip.status = 'active')))
$fn$;
--
-- Live organization RBAC for one principal, permission and target.
CREATE FUNCTION cob3_identity.rbac_permits(
        p_tenant_id uuid, p_organization_id uuid, p_principal_id uuid, p_permission_id uuid,
        p_target_type text, p_target_id uuid, p_at timestamptz)
    RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path = pg_catalog, pg_temp
AS $fn$
    SELECT EXISTS (
        SELECT 1
          FROM cob3_identity.permissions perm
          JOIN cob3_identity.role_permissions rp
            ON rp.tenant_id = perm.tenant_id AND rp.permission_id = perm.permission_id
          JOIN cob3_identity.roles r
            ON r.tenant_id = rp.tenant_id AND r.role_id = rp.role_id
          JOIN cob3_identity.role_bindings rb
            ON rb.tenant_id = r.tenant_id AND rb.role_id = r.role_id
         WHERE perm.tenant_id = p_tenant_id
           AND perm.permission_id = p_permission_id
           AND perm.status = 'active'
           AND perm.permission_class = 'organization'
           AND r.status = 'active'
           AND r.role_class = 'organization'
           AND rb.organization_id = p_organization_id
           AND rb.status = 'active'
           AND rb.valid_from <= p_at
           AND (rb.valid_until IS NULL OR rb.valid_until > p_at)
           AND (rb.principal_id = p_principal_id
                OR rb.team_id IN (SELECT cob3_identity.effective_team_ids(p_tenant_id, p_organization_id, p_principal_id, p_at)))
           AND cob3_identity.scope_covers_target(rb.tenant_id, rb.organization_id, rb.scope_id, rb.team_id,
                                                 perm.resource_type, p_target_type, p_target_id, p_at))
$fn$;
--
CREATE FUNCTION cob3_identity.tenant_control_permits(p_tenant_id uuid, p_principal_id uuid, p_permission_id uuid, p_at timestamptz)
    RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path = pg_catalog, pg_temp
AS $fn$
    SELECT EXISTS (
        SELECT 1
          FROM cob3_identity.tenant_role_bindings b
          JOIN cob3_identity.principals pr
            ON pr.tenant_id = b.tenant_id AND pr.principal_id = b.principal_id
          JOIN cob3_identity.roles r
            ON r.tenant_id = b.tenant_id AND r.role_id = b.role_id
          JOIN cob3_identity.role_permissions rp
            ON rp.tenant_id = r.tenant_id AND rp.role_id = r.role_id
          JOIN cob3_identity.permissions perm
            ON perm.tenant_id = rp.tenant_id AND perm.permission_id = rp.permission_id
         WHERE b.tenant_id = p_tenant_id
           AND b.principal_id = p_principal_id
           AND pr.principal_type IN ('human', 'service_account')
           AND b.status = 'active'
           AND b.valid_from <= p_at
           AND (b.valid_until IS NULL OR b.valid_until > p_at)
           AND r.status = 'active'
           AND r.role_class = 'tenant_control'
           AND perm.permission_id = p_permission_id
           AND perm.status = 'active'
           AND perm.permission_class = 'tenant_control')
$fn$;
--
-- ---------------------------------------------------------------------------
-- evaluate_access: authoritative decision for one operation.
--   p_target_type/p_target_id: use ('tenant', tenant_id) for tenant-control
--   permissions and ('organization', organization_id) for organization-
--   administered resources. Any other target requires the Catalog resolver.
-- ---------------------------------------------------------------------------
CREATE FUNCTION cob3_identity.evaluate_access(
        p_tenant_id               uuid,
        p_organization_id         uuid,
        p_principal_id            uuid,
        p_session_id              uuid,
        p_credential_id           uuid,
        p_permission_code         text,
        p_target_type             text,
        p_target_id               uuid,
        p_at                      timestamptz DEFAULT now(),
        p_initiating_principal_id uuid DEFAULT NULL,
        OUT allowed                     boolean,
        OUT reason_code                 text,
        OUT decision_path               text,
        OUT matched_grant_id            uuid,
        OUT matched_grant_permission_id uuid,
        OUT requires_approval           boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path = pg_catalog, pg_temp
AS $fn$
#variable_conflict use_column
DECLARE
    v_principal cob3_identity.principals%ROWTYPE;
    v_perm      cob3_identity.permissions%ROWTYPE;
    v_session   cob3_identity.auth_sessions%ROWTYPE;
    v_cred      cob3_identity.principal_credentials%ROWTYPE;
    v_grant     cob3_identity.authorization_grants%ROWTYPE;
    v_cred_id   uuid := p_credential_id;
    v_auto_ctx  boolean;
    v_entry     uuid;
    v_requires  boolean;
BEGIN
    allowed := false;
    requires_approval := false;
    decision_path := 'none';
--
    IF p_tenant_id IS NULL OR p_principal_id IS NULL OR p_permission_code IS NULL OR p_at IS NULL THEN
        reason_code := 'missing_context'; RETURN;
    END IF;
    IF NOT cob3_identity.tenant_is_active(p_tenant_id) THEN
        reason_code := 'tenant_not_active'; RETURN;
    END IF;
    SELECT p.* INTO v_principal
      FROM cob3_identity.principals p
     WHERE p.tenant_id = p_tenant_id AND p.principal_id = p_principal_id;
    IF NOT FOUND THEN
        reason_code := 'principal_not_found'; RETURN;
    END IF;
    IF NOT cob3_identity.principal_is_eligible(p_tenant_id, p_principal_id, p_at) THEN
        reason_code := 'principal_not_eligible'; RETURN;
    END IF;
    SELECT x.* INTO v_perm
      FROM cob3_identity.permissions x
     WHERE x.tenant_id = p_tenant_id AND x.permission_code = p_permission_code;
    IF NOT FOUND THEN
        reason_code := 'unknown_permission'; RETURN;
    END IF;
    IF v_perm.status <> 'active' THEN
        reason_code := 'permission_inactive'; RETURN;
    END IF;
--
    IF p_session_id IS NOT NULL THEN
        SELECT s.* INTO v_session
          FROM cob3_identity.auth_sessions s
         WHERE s.tenant_id = p_tenant_id AND s.session_id = p_session_id;
        IF NOT FOUND THEN
            reason_code := 'session_not_found'; RETURN;
        END IF;
        IF v_session.principal_id <> p_principal_id THEN
            reason_code := 'session_principal_mismatch'; RETURN;
        END IF;
        IF NOT cob3_identity.session_is_valid(p_tenant_id, p_session_id, p_at) THEN
            reason_code := 'session_invalid'; RETURN;
        END IF;
--
        IF v_session.session_kind = 'interactive' THEN
            -- An API key is never promoted into an interactive session.
            IF v_cred_id IS NOT NULL THEN
                reason_code := 'credential_not_permitted_in_interactive_session'; RETURN;
            END IF;
            decision_path := 'interactive_rbac';
            IF v_principal.principal_type <> 'human' THEN
                reason_code := 'interactive_requires_human'; RETURN;
            END IF;
            IF v_perm.permission_class = 'tenant_control' THEN
                IF cob3_identity.tenant_control_permits(p_tenant_id, p_principal_id, v_perm.permission_id, p_at) THEN
                    allowed := true; reason_code := 'allowed';
                ELSE
                    reason_code := 'tenant_rbac_denied';
                END IF;
                RETURN;
            END IF;
            IF p_organization_id IS NULL OR v_session.organization_id IS DISTINCT FROM p_organization_id THEN
                reason_code := 'session_organization_mismatch'; RETURN;
            END IF;
            IF NOT cob3_identity.membership_is_effective(p_tenant_id, p_organization_id, p_principal_id, p_at) THEN
                reason_code := 'membership_not_effective'; RETURN;
            END IF;
            IF NOT cob3_identity.rbac_permits(p_tenant_id, p_organization_id, p_principal_id, v_perm.permission_id,
                                              p_target_type, p_target_id, p_at) THEN
                reason_code := 'rbac_denied'; RETURN;
            END IF;
            allowed := true; reason_code := 'allowed'; RETURN;
        END IF;
--
        -- Noninteractive session: bounded by its grant (and credential, if any).
        IF v_cred_id IS NOT NULL AND v_cred_id IS DISTINCT FROM v_session.credential_id THEN
            reason_code := 'session_credential_mismatch'; RETURN;
        END IF;
        v_cred_id := v_session.credential_id;
        IF v_session.organization_id IS DISTINCT FROM p_organization_id THEN
            reason_code := 'session_organization_mismatch'; RETURN;
        END IF;
        SELECT g.* INTO v_grant
          FROM cob3_identity.authorization_grants g
         WHERE g.tenant_id = p_tenant_id
           AND g.organization_id = v_session.organization_id
           AND g.authorization_grant_id = v_session.authorization_grant_id;
    ELSIF v_cred_id IS NULL THEN
        reason_code := 'no_authenticated_context'; RETURN;
    END IF;
--
    -- Grant / credential path.
    decision_path := CASE WHEN v_cred_id IS NOT NULL THEN 'credential_grant' ELSE 'federated_grant' END;
    IF v_perm.permission_class <> 'organization' THEN
        reason_code := 'tenant_control_requires_interactive'; RETURN;
    END IF;
    IF p_organization_id IS NULL THEN
        reason_code := 'organization_context_required'; RETURN;
    END IF;
    IF v_cred_id IS NOT NULL THEN
        SELECT c.* INTO v_cred
          FROM cob3_identity.principal_credentials c
         WHERE c.tenant_id = p_tenant_id AND c.credential_id = v_cred_id;
        IF NOT FOUND
           OR v_cred.organization_id <> p_organization_id
           OR v_cred.principal_id <> p_principal_id
           OR v_cred.status <> 'active'
           OR v_cred.expires_at <= p_at THEN
            reason_code := 'credential_invalid'; RETURN;
        END IF;
        IF v_grant.authorization_grant_id IS NULL THEN
            SELECT g.* INTO v_grant
              FROM cob3_identity.authorization_grants g
             WHERE g.tenant_id = p_tenant_id
               AND g.organization_id = p_organization_id
               AND g.authorization_grant_id = v_cred.authorization_grant_id;
        ELSIF v_grant.authorization_grant_id <> v_cred.authorization_grant_id THEN
            reason_code := 'credential_grant_mismatch'; RETURN;
        END IF;
    END IF;
    IF v_grant.authorization_grant_id IS NULL THEN
        reason_code := 'grant_not_found'; RETURN;
    END IF;
    IF v_grant.organization_id <> p_organization_id OR v_grant.grantee_principal_id <> p_principal_id THEN
        reason_code := 'grant_principal_mismatch'; RETURN;
    END IF;
    IF v_grant.status <> 'active' OR v_grant.valid_from > p_at OR v_grant.valid_until <= p_at THEN
        reason_code := 'grant_not_effective'; RETURN;
    END IF;
    matched_grant_id := v_grant.authorization_grant_id;
--
    IF NOT cob3_identity.membership_is_effective(p_tenant_id, p_organization_id, p_principal_id, p_at) THEN
        reason_code := 'membership_not_effective'; RETURN;
    END IF;
    IF v_grant.grantor_principal_id <> p_principal_id THEN
        IF NOT cob3_identity.principal_is_eligible(p_tenant_id, v_grant.grantor_principal_id, p_at)
           OR NOT cob3_identity.membership_is_effective(p_tenant_id, p_organization_id, v_grant.grantor_principal_id, p_at) THEN
            reason_code := 'grantor_not_eligible'; RETURN;
        END IF;
    END IF;
--
    -- Immutable usage restrictions.
    v_auto_ctx := v_principal.principal_type = 'automation' OR COALESCE(v_cred.credential_usage = 'automation', false);
    IF v_auto_ctx THEN
        IF NOT v_perm.automation_allowed OR v_perm.is_identity_management THEN
            reason_code := 'automation_restricted'; RETURN;
        END IF;
    ELSIF v_perm.is_identity_management THEN
        IF NOT (COALESCE(v_cred.credential_usage, '') = 'provisioning' AND v_principal.principal_type = 'service_account') THEN
            reason_code := 'iam_requires_interactive_or_provisioning'; RETURN;
        END IF;
    END IF;
    IF NOT v_perm.is_delegable THEN
        reason_code := 'permission_not_delegable'; RETURN;
    END IF;
--
    -- Approved entries matching operation + scope. Approval requirement is
    -- aggregated over ALL applicable entries of the grant (strictest wins);
    -- a credential additionally needs one applicable entry it is bound to.
    SELECT bool_or(e.requires_human_approval),
           (array_agg(e.authorization_grant_permission_id ORDER BY e.authorization_grant_permission_id)
                FILTER (WHERE v_cred_id IS NULL OR EXISTS (
                    SELECT 1
                      FROM cob3_identity.credential_permission_bindings b
                     WHERE b.tenant_id = e.tenant_id
                       AND b.organization_id = e.organization_id
                       AND b.authorization_grant_id = e.authorization_grant_id
                       AND b.credential_id = v_cred_id
                       AND b.authorization_grant_permission_id = e.authorization_grant_permission_id)))[1]
      INTO v_requires, v_entry
      FROM cob3_identity.authorization_grant_permissions e
     WHERE e.tenant_id = p_tenant_id
       AND e.organization_id = p_organization_id
       AND e.authorization_grant_id = v_grant.authorization_grant_id
       AND e.permission_id = v_perm.permission_id
       AND cob3_identity.scope_covers_target(e.tenant_id, e.organization_id, e.scope_id, NULL,
                                             v_perm.resource_type, p_target_type, p_target_id, p_at);
    IF v_entry IS NULL THEN
        reason_code := CASE WHEN v_requires IS NULL THEN 'no_matching_grant_entry' ELSE 'credential_subset_denied' END;
        RETURN;
    END IF;
    matched_grant_permission_id := v_entry;
    requires_approval := COALESCE(v_requires, false);
--
    -- Live RBAC of grantee and grantor.
    IF NOT cob3_identity.rbac_permits(p_tenant_id, p_organization_id, p_principal_id, v_perm.permission_id,
                                      p_target_type, p_target_id, p_at) THEN
        reason_code := 'grantee_rbac_denied'; RETURN;
    END IF;
    IF v_grant.grantor_principal_id <> p_principal_id
       AND NOT cob3_identity.rbac_permits(p_tenant_id, p_organization_id, v_grant.grantor_principal_id, v_perm.permission_id,
                                          p_target_type, p_target_id, p_at) THEN
        reason_code := 'grantor_rbac_denied'; RETURN;
    END IF;
--
    -- Interactive assistance: the initiating user's live access is intersected too.
    IF p_initiating_principal_id IS NOT NULL AND p_initiating_principal_id <> p_principal_id THEN
        IF NOT cob3_identity.principal_is_eligible(p_tenant_id, p_initiating_principal_id, p_at)
           OR NOT cob3_identity.membership_is_effective(p_tenant_id, p_organization_id, p_initiating_principal_id, p_at)
           OR NOT cob3_identity.rbac_permits(p_tenant_id, p_organization_id, p_initiating_principal_id, v_perm.permission_id,
                                             p_target_type, p_target_id, p_at) THEN
            reason_code := 'initiator_denied'; RETURN;
        END IF;
    END IF;
--
    allowed := true;
    reason_code := 'allowed';
    RETURN;
END
$fn$;
--
-- ---------------------------------------------------------------------------
-- Context predicates for RLS and routines
-- ---------------------------------------------------------------------------
CREATE FUNCTION cob3_identity.ctx_auth_valid()
    RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path = pg_catalog, pg_temp
AS $fn$
DECLARE
    v_tenant    uuid := cob3_identity.ctx_tenant_id();
    v_org       uuid := cob3_identity.ctx_organization_id();
    v_principal uuid := cob3_identity.ctx_principal_id();
    v_session   uuid := cob3_identity.ctx_session_id();
    v_cred      uuid := cob3_identity.ctx_credential_id();
    v_s         cob3_identity.auth_sessions%ROWTYPE;
    v_c         cob3_identity.principal_credentials%ROWTYPE;
BEGIN
    IF v_tenant IS NULL OR v_principal IS NULL OR (v_session IS NULL AND v_cred IS NULL) THEN
        RETURN false;
    END IF;
    IF NOT cob3_identity.tenant_is_active(v_tenant)
       OR NOT cob3_identity.principal_is_eligible(v_tenant, v_principal, pg_catalog.now()) THEN
        RETURN false;
    END IF;
    IF v_session IS NOT NULL THEN
        SELECT s.* INTO v_s
          FROM cob3_identity.auth_sessions s
         WHERE s.tenant_id = v_tenant AND s.session_id = v_session;
        IF NOT FOUND OR v_s.principal_id <> v_principal
           OR NOT cob3_identity.session_is_valid(v_tenant, v_session, pg_catalog.now())
           OR v_s.organization_id IS DISTINCT FROM v_org THEN
            RETURN false;
        END IF;
        IF v_s.session_kind = 'interactive' THEN
            IF v_cred IS NOT NULL THEN
                RETURN false;
            END IF;
            RETURN true;
        END IF;
        IF NOT cob3_identity.grant_is_effective(v_tenant, v_s.organization_id, v_s.authorization_grant_id, v_principal, pg_catalog.now()) THEN
            RETURN false;
        END IF;
        IF v_s.credential_id IS NULL THEN
            RETURN v_cred IS NULL;
        END IF;
        IF v_cred IS NOT NULL AND v_cred <> v_s.credential_id THEN
            RETURN false;
        END IF;
        v_cred := v_s.credential_id;
    END IF;
    IF v_org IS NULL THEN
        RETURN false;
    END IF;
    SELECT c.* INTO v_c
      FROM cob3_identity.principal_credentials c
     WHERE c.tenant_id = v_tenant AND c.credential_id = v_cred;
    IF NOT FOUND OR v_c.principal_id <> v_principal OR v_c.organization_id <> v_org
       OR v_c.status <> 'active' OR v_c.expires_at <= pg_catalog.now() THEN
        RETURN false;
    END IF;
    RETURN cob3_identity.grant_is_effective(v_tenant, v_org, v_c.authorization_grant_id, v_principal, pg_catalog.now());
END
$fn$;
--
CREATE FUNCTION cob3_identity.ctx_is_tenant_member()
    RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path = pg_catalog, pg_temp
AS $fn$ SELECT cob3_identity.ctx_auth_valid() $fn$;
--
CREATE FUNCTION cob3_identity.ctx_is_interactive()
    RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path = pg_catalog, pg_temp
AS $fn$
    SELECT cob3_identity.ctx_credential_id() IS NULL
       AND EXISTS (SELECT 1 FROM cob3_identity.auth_sessions s
                    WHERE s.tenant_id = cob3_identity.ctx_tenant_id()
                      AND s.session_id = cob3_identity.ctx_session_id()
                      AND s.session_kind = 'interactive')
       AND cob3_identity.ctx_auth_valid()
$fn$;
--
CREATE FUNCTION cob3_identity.ctx_in_org()
    RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path = pg_catalog, pg_temp
AS $fn$
    SELECT cob3_identity.ctx_organization_id() IS NOT NULL
       AND cob3_identity.ctx_auth_valid()
       AND cob3_identity.membership_is_effective(cob3_identity.ctx_tenant_id(), cob3_identity.ctx_organization_id(),
                                                 cob3_identity.ctx_principal_id(), pg_catalog.now())
$fn$;
--
-- Membership-based visibility of an organization. Credential and
-- noninteractive contexts are bound to their own organization.
CREATE FUNCTION cob3_identity.ctx_is_member_of(p_organization_id uuid)
    RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path = pg_catalog, pg_temp
AS $fn$
    SELECT cob3_identity.ctx_auth_valid()
       AND cob3_identity.membership_is_effective(cob3_identity.ctx_tenant_id(), p_organization_id,
                                                 cob3_identity.ctx_principal_id(), pg_catalog.now())
       AND (cob3_identity.ctx_is_interactive() OR p_organization_id = cob3_identity.ctx_organization_id())
$fn$;
--
CREATE FUNCTION cob3_identity.ctx_is_tenant_controller()
    RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path = pg_catalog, pg_temp
AS $fn$
    SELECT cob3_identity.ctx_is_interactive()
       AND EXISTS (
           SELECT 1
             FROM cob3_identity.tenant_role_bindings b
             JOIN cob3_identity.roles r ON r.tenant_id = b.tenant_id AND r.role_id = b.role_id
            WHERE b.tenant_id = cob3_identity.ctx_tenant_id()
              AND b.principal_id = cob3_identity.ctx_principal_id()
              AND b.status = 'active'
              AND b.valid_from <= pg_catalog.now()
              AND (b.valid_until IS NULL OR b.valid_until > pg_catalog.now())
              AND r.status = 'active'
              AND r.role_class = 'tenant_control')
$fn$;
--
CREATE FUNCTION cob3_identity.ctx_has_org_permission(p_permission_code text)
    RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path = pg_catalog, pg_temp
AS $fn$
    SELECT COALESCE((
        SELECT d.allowed
          FROM cob3_identity.evaluate_access(
                   cob3_identity.ctx_tenant_id(), cob3_identity.ctx_organization_id(), cob3_identity.ctx_principal_id(),
                   cob3_identity.ctx_session_id(), cob3_identity.ctx_credential_id(),
                   p_permission_code, 'organization', cob3_identity.ctx_organization_id(), pg_catalog.now(), NULL) AS d), false)
       AND cob3_identity.ctx_auth_valid()
$fn$;
--
CREATE FUNCTION cob3_identity.ctx_has_tenant_permission(p_permission_code text)
    RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path = pg_catalog, pg_temp
AS $fn$
    SELECT COALESCE((
        SELECT d.allowed
          FROM cob3_identity.evaluate_access(
                   cob3_identity.ctx_tenant_id(), cob3_identity.ctx_organization_id(), cob3_identity.ctx_principal_id(),
                   cob3_identity.ctx_session_id(), cob3_identity.ctx_credential_id(),
                   p_permission_code, 'tenant', cob3_identity.ctx_tenant_id(), pg_catalog.now(), NULL) AS d), false)
       AND cob3_identity.ctx_auth_valid()
$fn$;
--
-- Directory visibility: self, members of the current organization (for an
-- active member of it), or tenant controllers. Not blanket tenant visibility.
CREATE FUNCTION cob3_identity.ctx_can_view_principal(p_principal_id uuid)
    RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path = pg_catalog, pg_temp
AS $fn$
    SELECT cob3_identity.ctx_auth_valid()
       AND (p_principal_id = cob3_identity.ctx_principal_id()
            OR (cob3_identity.ctx_in_org()
                AND EXISTS (SELECT 1 FROM cob3_identity.organization_memberships m
                             WHERE m.tenant_id = cob3_identity.ctx_tenant_id()
                               AND m.organization_id = cob3_identity.ctx_organization_id()
                               AND m.principal_id = p_principal_id))
            OR cob3_identity.ctx_is_tenant_controller())
$fn$;
--
-- Who may change a principal (status, display name, profile).
CREATE FUNCTION cob3_identity.ctx_can_manage_principal(p_principal_id uuid)
    RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path = pg_catalog, pg_temp
AS $fn$
DECLARE
    v_tenant uuid := cob3_identity.ctx_tenant_id();
    v_org    uuid := cob3_identity.ctx_organization_id();
    v_p      cob3_identity.principals%ROWTYPE;
BEGIN
    IF NOT cob3_identity.ctx_auth_valid() THEN
        RETURN false;
    END IF;
    SELECT p.* INTO v_p FROM cob3_identity.principals p
     WHERE p.tenant_id = v_tenant AND p.principal_id = p_principal_id;
    IF NOT FOUND THEN
        RETURN false;
    END IF;
    -- Creation flow: a principal created in this transaction by this actor.
    IF v_p.created_at = pg_catalog.now() AND v_p.created_by = cob3_identity.ctx_actor() THEN
        RETURN true;
    END IF;
    IF v_p.principal_type = 'human' THEN
        RETURN cob3_identity.ctx_has_tenant_permission('tenant.manage_administrators')
            OR (cob3_identity.ctx_has_org_permission('organization.manage_members')
                AND EXISTS (SELECT 1 FROM cob3_identity.organization_memberships m
                             WHERE m.tenant_id = v_tenant AND m.organization_id = v_org
                               AND m.principal_id = p_principal_id));
    ELSIF v_p.principal_type = 'service_account' THEN
        RETURN EXISTS (SELECT 1 FROM cob3_identity.service_accounts s
                        WHERE s.tenant_id = v_tenant AND s.principal_id = p_principal_id
                          AND s.organization_id = v_org)
           AND cob3_identity.ctx_has_org_permission('service_account.manage');
    ELSE
        RETURN EXISTS (SELECT 1 FROM cob3_identity.automation_profiles a
                        WHERE a.tenant_id = v_tenant AND a.principal_id = p_principal_id
                          AND a.organization_id = v_org)
           AND (cob3_identity.ctx_has_org_permission('automation.manage')
                OR cob3_identity.ctx_has_org_permission('automation.revoke'));
    END IF;
END
$fn$;
--
CREATE FUNCTION cob3_identity.ctx_can_view_grant(p_organization_id uuid, p_grant_id uuid)
    RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path = pg_catalog, pg_temp
AS $fn$
    SELECT p_organization_id = cob3_identity.ctx_organization_id()
       AND cob3_identity.ctx_in_org()
       AND (EXISTS (SELECT 1 FROM cob3_identity.authorization_grants g
                     WHERE g.tenant_id = cob3_identity.ctx_tenant_id()
                       AND g.organization_id = p_organization_id
                       AND g.authorization_grant_id = p_grant_id
                       AND cob3_identity.ctx_principal_id() IN (g.grantor_principal_id, g.grantee_principal_id, g.authorized_by_principal_id))
            OR cob3_identity.ctx_has_org_permission('grant.revoke')
            OR cob3_identity.ctx_has_org_permission('audit.read'))
$fn$;
--
CREATE FUNCTION cob3_identity.ctx_can_view_credential(p_organization_id uuid, p_credential_id uuid)
    RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path = pg_catalog, pg_temp
AS $fn$
    SELECT p_organization_id = cob3_identity.ctx_organization_id()
       AND cob3_identity.ctx_in_org()
       AND (EXISTS (SELECT 1 FROM cob3_identity.principal_credentials c
                     WHERE c.tenant_id = cob3_identity.ctx_tenant_id()
                       AND c.organization_id = p_organization_id
                       AND c.credential_id = p_credential_id
                       AND c.principal_id = cob3_identity.ctx_principal_id())
            OR cob3_identity.ctx_has_org_permission('credential.revoke'))
$fn$;
--
CREATE FUNCTION cob3_identity.role_is_system(p_tenant_id uuid, p_role_id uuid)
    RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path = pg_catalog, pg_temp
AS $fn$
    SELECT COALESCE((SELECT r.is_system FROM cob3_identity.roles r
                      WHERE r.tenant_id = p_tenant_id AND r.role_id = p_role_id), true)
$fn$;
--
-- Raise unless the current context holds the permission (routine guard).
CREATE FUNCTION cob3_identity.require_ctx_permission(p_permission_code text, p_target_type text DEFAULT 'organization')
    RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path = pg_catalog, pg_temp
AS $fn$
DECLARE
    v_target uuid := CASE WHEN p_target_type = 'tenant' THEN cob3_identity.ctx_tenant_id() ELSE cob3_identity.ctx_organization_id() END;
    d        record;
BEGIN
    IF NOT cob3_identity.ctx_auth_valid() THEN
        RAISE EXCEPTION USING ERRCODE = 'SKCTX', MESSAGE = 'No valid authenticated request context (tenant, principal, session or credential).';
    END IF;
    SELECT * INTO d FROM cob3_identity.evaluate_access(
        cob3_identity.ctx_tenant_id(), cob3_identity.ctx_organization_id(), cob3_identity.ctx_principal_id(),
        cob3_identity.ctx_session_id(), cob3_identity.ctx_credential_id(),
        p_permission_code, p_target_type, v_target, pg_catalog.now(), NULL);
    IF NOT d.allowed THEN
        RAISE EXCEPTION USING ERRCODE = 'SKAUZ',
            MESSAGE = pg_catalog.format('Permission %s denied: %s.', p_permission_code, d.reason_code);
    END IF;
END
$fn$;
--
-- >>> src/60_tenant_logic.sql
-- =============================================================================
-- 60  TENANT COMMERCIAL LOGIC AND INVARIANT TRIGGERS
-- =============================================================================
--
-- ---------------------------------------------------------------------------
-- Entitlement resolution
--   1. one eligible subscription (trialing/active/past_due); none => disabled
--   2. the contract segment effective at p_at (optionally the latest earlier
--      segment, assuming renewal, for future allocation validation)
--   3. plan entitlement (missing => disabled, never unlimited)
--   4. at most one approved override, which REPLACES the plan entitlement
-- ---------------------------------------------------------------------------
CREATE FUNCTION cob3_tenant.effective_entitlement(
        p_tenant_id       uuid,
        p_feature_id      uuid,
        p_at              timestamptz,
        p_assume_renewal  boolean DEFAULT false,
        OUT is_enabled             boolean,
        OUT is_unlimited           boolean,
        OUT limit_value            numeric,
        OUT reset_period           text,
        OUT source                 text,
        OUT subscription_id        uuid,
        OUT subscription_period_id uuid,
        OUT billing_period_key     text,
        OUT plan_version_id        uuid)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path = pg_catalog, pg_temp
AS $fn$
#variable_conflict use_column
DECLARE
    v_sub    uuid;
    v_period cob3_tenant.subscription_periods%ROWTYPE;
    v_ent    cob3_tenant.plan_entitlements%ROWTYPE;
    v_ov     cob3_tenant.tenant_entitlement_overrides%ROWTYPE;
BEGIN
    is_enabled := false; is_unlimited := false; limit_value := NULL; reset_period := 'none'; source := 'no_subscription';
    SELECT s.subscription_id INTO v_sub
      FROM cob3_tenant.subscriptions s
     WHERE s.tenant_id = p_tenant_id AND s.status IN ('trialing', 'active', 'past_due');
    IF v_sub IS NULL THEN
        RETURN;
    END IF;
    subscription_id := v_sub;
    source := 'none';
    SELECT sp.* INTO v_period
      FROM cob3_tenant.subscription_periods sp
     WHERE sp.tenant_id = p_tenant_id AND sp.subscription_id = v_sub
       AND sp.period_start <= p_at AND sp.period_end > p_at;
    IF v_period.subscription_period_id IS NULL AND p_assume_renewal THEN
        SELECT sp.* INTO v_period
          FROM cob3_tenant.subscription_periods sp
         WHERE sp.tenant_id = p_tenant_id AND sp.subscription_id = v_sub AND sp.period_start <= p_at
         ORDER BY sp.period_start DESC
         LIMIT 1;
    END IF;
    IF v_period.subscription_period_id IS NOT NULL THEN
        subscription_period_id := v_period.subscription_period_id;
        billing_period_key := v_period.billing_period_key;
        plan_version_id := v_period.plan_version_id;
        SELECT pe.* INTO v_ent
          FROM cob3_tenant.plan_entitlements pe
         WHERE pe.plan_version_id = v_period.plan_version_id AND pe.feature_id = p_feature_id;
        IF v_ent.plan_entitlement_id IS NOT NULL THEN
            is_enabled := v_ent.is_enabled; is_unlimited := v_ent.is_unlimited;
            limit_value := v_ent.limit_value; reset_period := v_ent.reset_period; source := 'plan';
        END IF;
    END IF;
    SELECT o.* INTO v_ov
      FROM cob3_tenant.tenant_entitlement_overrides o
     WHERE o.tenant_id = p_tenant_id AND o.feature_id = p_feature_id AND o.status = 'approved'
       AND o.valid_from <= p_at AND o.valid_until > p_at;
    IF v_ov.tenant_entitlement_override_id IS NOT NULL THEN
        is_enabled := v_ov.is_enabled; is_unlimited := v_ov.is_unlimited;
        limit_value := v_ov.limit_value; reset_period := v_ov.reset_period; source := 'override';
    END IF;
    RETURN;
END
$fn$;
--
-- Runtime wrapper: tenant comes from the authenticated request context.
CREATE FUNCTION cob3_tenant.resolve_entitlement(p_feature_code text, p_at timestamptz DEFAULT now())
    RETURNS TABLE (feature_code text, value_type text, measurement_kind text, unit_code text,
                   is_enabled boolean, is_unlimited boolean, limit_value numeric, reset_period text, source text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path = pg_catalog, pg_temp
AS $fn$
BEGIN
    IF NOT cob3_identity.ctx_auth_valid() THEN
        RAISE EXCEPTION USING ERRCODE = 'SKCTX', MESSAGE = 'No valid authenticated request context.';
    END IF;
    RETURN QUERY SELECT * FROM cob3_tenant.resolve_tenant_entitlement(cob3_identity.ctx_tenant_id(), p_feature_code, p_at);
END
$fn$;
--
-- Platform wrapper (commercial/provisioning roles only).
CREATE FUNCTION cob3_tenant.resolve_tenant_entitlement(p_tenant_id uuid, p_feature_code text, p_at timestamptz DEFAULT now())
    RETURNS TABLE (feature_code text, value_type text, measurement_kind text, unit_code text,
                   is_enabled boolean, is_unlimited boolean, limit_value numeric, reset_period text, source text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path = pg_catalog, pg_temp
AS $fn$
    SELECT f.feature_code::text, f.value_type::text, f.measurement_kind::text, f.unit_code::text,
           e.is_enabled, e.is_unlimited, e.limit_value, e.reset_period, e.source
      FROM cob3_tenant.features f
     CROSS JOIN LATERAL cob3_tenant.effective_entitlement(p_tenant_id, f.feature_id, p_at, false) AS e
     WHERE f.feature_code = p_feature_code
$fn$;
--
-- Capability check. Onboarding (tenant still 'provisioning') is exempt; a
-- retired feature is no longer commercially governed.
CREATE FUNCTION cob3_tenant.assert_feature_enabled(p_tenant_id uuid, p_feature_code text)
    RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path = pg_catalog, pg_temp
AS $fn$
DECLARE
    v_status  text;
    v_feature cob3_tenant.features%ROWTYPE;
    v_e       record;
BEGIN
    SELECT t.status INTO v_status FROM cob3_tenant.tenants t WHERE t.tenant_id = p_tenant_id;
    IF v_status = 'provisioning' THEN
        RETURN;
    END IF;
    SELECT f.* INTO v_feature FROM cob3_tenant.features f WHERE f.feature_code = p_feature_code;
    IF v_feature.feature_id IS NULL OR v_feature.status <> 'active' THEN
        RETURN;
    END IF;
    SELECT * INTO v_e FROM cob3_tenant.effective_entitlement(p_tenant_id, v_feature.feature_id, pg_catalog.now(), false);
    IF NOT v_e.is_enabled THEN
        RAISE EXCEPTION USING ERRCODE = 'SKENT',
            MESSAGE = pg_catalog.format('Tenant is not entitled to feature %s (%s).', p_feature_code, v_e.source);
    END IF;
END
$fn$;
--
-- Gauge quota check. Callers take cob3_identity.xact_lock('quota', ...) and
-- count AFTER the lock (fresh snapshot), then call this before commit.
CREATE FUNCTION cob3_tenant.assert_gauge_capacity(
        p_tenant_id uuid, p_organization_id uuid, p_feature_code text, p_tenant_usage numeric, p_org_usage numeric)
    RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path = pg_catalog, pg_temp
AS $fn$
DECLARE
    v_status  text;
    v_feature cob3_tenant.features%ROWTYPE;
    v_e       record;
    v_alloc   numeric;
BEGIN
    SELECT t.status INTO v_status FROM cob3_tenant.tenants t WHERE t.tenant_id = p_tenant_id;
    IF v_status = 'provisioning' THEN
        RETURN;
    END IF;
    SELECT f.* INTO v_feature FROM cob3_tenant.features f WHERE f.feature_code = p_feature_code;
    IF v_feature.feature_id IS NULL OR v_feature.status <> 'active' THEN
        RETURN;
    END IF;
    SELECT * INTO v_e FROM cob3_tenant.effective_entitlement(p_tenant_id, v_feature.feature_id, pg_catalog.now(), false);
    IF NOT v_e.is_enabled THEN
        RAISE EXCEPTION USING ERRCODE = 'SKQTA',
            MESSAGE = pg_catalog.format('Quota %s is not entitled for this tenant (%s).', p_feature_code, v_e.source);
    END IF;
    IF NOT v_e.is_unlimited AND p_tenant_usage > v_e.limit_value THEN
        RAISE EXCEPTION USING ERRCODE = 'SKQTA',
            MESSAGE = pg_catalog.format('Quota %s exceeded: %s in use, tenant limit %s.', p_feature_code, p_tenant_usage, v_e.limit_value);
    END IF;
    IF p_organization_id IS NOT NULL AND EXISTS (
           SELECT 1 FROM cob3_tenant.organization_quota_allocations a
            WHERE a.tenant_id = p_tenant_id AND a.feature_id = v_feature.feature_id AND a.status = 'active'
              AND a.valid_from <= pg_catalog.now() AND a.valid_until > pg_catalog.now()) THEN
        SELECT a.allocated_limit INTO v_alloc
          FROM cob3_tenant.organization_quota_allocations a
         WHERE a.tenant_id = p_tenant_id AND a.organization_id = p_organization_id
           AND a.feature_id = v_feature.feature_id AND a.status = 'active'
           AND a.valid_from <= pg_catalog.now() AND a.valid_until > pg_catalog.now();
        IF v_alloc IS NULL OR p_org_usage > v_alloc THEN
            RAISE EXCEPTION USING ERRCODE = 'SKQTA',
                MESSAGE = pg_catalog.format('Quota %s exceeded for organization %s: %s in use, allocation %s.',
                            p_feature_code, p_organization_id, p_org_usage, COALESCE(v_alloc::text, 'none (partitioned capacity)'));
        END IF;
    END IF;
END
$fn$;
--
-- Sum of simultaneous active allocations must not exceed the effective
-- tenant entitlement at any change boundary within the window. Serialized per
-- tenant/feature with an advisory lock; reads happen after the lock.
CREATE FUNCTION cob3_tenant.validate_allocations(p_tenant_id uuid, p_feature_id uuid, p_from timestamptz, p_until timestamptz)
    RETURNS void
    LANGUAGE plpgsql VOLATILE SECURITY DEFINER
    SET search_path = pg_catalog, pg_temp
AS $fn$
DECLARE
    v_feature uuid;
    v_t       timestamptz;
    v_total   numeric;
    v_e       record;
BEGIN
    PERFORM cob3_identity.assert_isolation_safe();
    FOR v_feature IN
        SELECT DISTINCT a.feature_id
          FROM cob3_tenant.organization_quota_allocations a
         WHERE a.tenant_id = p_tenant_id
           AND (p_feature_id IS NULL OR a.feature_id = p_feature_id)
           AND a.status = 'active' AND a.valid_from < p_until AND a.valid_until > p_from
         ORDER BY a.feature_id
    LOOP
        PERFORM cob3_identity.xact_lock('allocation', p_tenant_id::text || ':' || v_feature::text);
        FOR v_t IN
            SELECT DISTINCT b.t FROM (
                SELECT p_from AS t
                UNION ALL
                SELECT a.valid_from FROM cob3_tenant.organization_quota_allocations a
                 WHERE a.tenant_id = p_tenant_id AND a.feature_id = v_feature AND a.status = 'active'
                   AND a.valid_from > p_from AND a.valid_from < p_until
                UNION ALL
                SELECT sp.period_start FROM cob3_tenant.subscription_periods sp
                 WHERE sp.tenant_id = p_tenant_id AND sp.period_start > p_from AND sp.period_start < p_until
                UNION ALL
                SELECT o.valid_from FROM cob3_tenant.tenant_entitlement_overrides o
                 WHERE o.tenant_id = p_tenant_id AND o.feature_id = v_feature AND o.valid_from > p_from AND o.valid_from < p_until
                UNION ALL
                SELECT o.valid_until FROM cob3_tenant.tenant_entitlement_overrides o
                 WHERE o.tenant_id = p_tenant_id AND o.feature_id = v_feature AND o.valid_until > p_from AND o.valid_until < p_until
            ) AS b
            ORDER BY 1
        LOOP
            SELECT COALESCE(sum(a.allocated_limit), 0) INTO v_total
              FROM cob3_tenant.organization_quota_allocations a
             WHERE a.tenant_id = p_tenant_id AND a.feature_id = v_feature AND a.status = 'active'
               AND a.valid_from <= v_t AND a.valid_until > v_t;
            IF v_total = 0 THEN
                CONTINUE;
            END IF;
            SELECT * INTO v_e FROM cob3_tenant.effective_entitlement(p_tenant_id, v_feature, v_t, true);
            IF v_e.is_enabled AND v_e.is_unlimited THEN
                CONTINUE;
            END IF;
            IF NOT v_e.is_enabled OR v_e.limit_value IS NULL OR v_total > v_e.limit_value THEN
                RAISE EXCEPTION USING ERRCODE = 'SKQTA',
                    MESSAGE = pg_catalog.format('Organization allocations for feature %s total %s at %s, exceeding the tenant entitlement (%s).',
                                v_feature, v_total, v_t,
                                CASE WHEN v_e.is_enabled THEN v_e.limit_value::text ELSE 'not entitled: ' || v_e.source END),
                    HINT = 'Reallocate before changing contract terms or adding allocations.';
            END IF;
        END LOOP;
    END LOOP;
END
$fn$;
--
-- Counter window key for usage counters.
CREATE FUNCTION cob3_tenant.counter_window_key(p_reset_period text, p_occurred_at timestamptz, p_billing_period_key text)
    RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path = pg_catalog, pg_temp
AS $fn$
    SELECT CASE
             WHEN p_reset_period = 'subscription_period' AND p_billing_period_key IS NOT NULL THEN 'sp:' || p_billing_period_key
             ELSE 'cm:' || pg_catalog.to_char(p_occurred_at AT TIME ZONE 'UTC', 'YYYY-MM')
           END
$fn$;
--
-- ---------------------------------------------------------------------------
-- Usage recording with idempotency, correction limits and hard counters.
-- ---------------------------------------------------------------------------
CREATE FUNCTION cob3_tenant.record_usage_internal(
        p_tenant_id              uuid,
        p_organization_id        uuid,
        p_feature_code           text,
        p_source_code            text,
        p_source_event_id        text,
        p_occurred_at            timestamptz,
        p_quantity               numeric,
        p_request_id             uuid,
        p_correction_of_event_id uuid,
        p_enforce_limit          boolean,
        OUT usage_event_id uuid,
        OUT duplicate      boolean)
    LANGUAGE plpgsql VOLATILE SECURITY DEFINER
    SET search_path = pg_catalog, pg_temp
AS $fn$
#variable_conflict use_column
DECLARE
    v_feature  cob3_tenant.features%ROWTYPE;
    v_original cob3_tenant.usage_events%ROWTYPE;
    v_existing cob3_tenant.usage_events%ROWTYPE;
    v_e        record;
    v_at       timestamptz := p_occurred_at;
    v_org      uuid := p_organization_id;
    v_window   text;
    v_tenant_used numeric;
    v_org_used    numeric;
    v_alloc       numeric;
    v_has_allocs  boolean;
    v_new_id      uuid;
BEGIN
    duplicate := false;
    PERFORM cob3_identity.assert_isolation_safe();
    SELECT f.* INTO v_feature FROM cob3_tenant.features f WHERE f.feature_code = p_feature_code;
    IF v_feature.feature_id IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = 'SKENT', MESSAGE = pg_catalog.format('Unknown feature %s.', p_feature_code);
    END IF;
    IF v_feature.measurement_kind <> 'counter' THEN
        RAISE EXCEPTION USING ERRCODE = 'SKINV',
            MESSAGE = pg_catalog.format('Feature %s is a %s; usage events measure counter features only.', p_feature_code, v_feature.measurement_kind);
    END IF;
    IF p_correction_of_event_id IS NOT NULL THEN
        -- Corrections are attributed to the original event's window and organization.
        SELECT e.* INTO v_original FROM cob3_tenant.usage_events e
         WHERE e.tenant_id = p_tenant_id AND e.usage_event_id = p_correction_of_event_id;
        IF v_original.usage_event_id IS NOT NULL THEN
            v_at := v_original.occurred_at;
        END IF;
    END IF;
--
    SELECT * INTO v_e FROM cob3_tenant.effective_entitlement(p_tenant_id, v_feature.feature_id, v_at, false);
    v_window := cob3_tenant.counter_window_key(v_e.reset_period, v_at, v_e.billing_period_key);
--
    -- Lock the tenant-total and organization counter rows (serializes consumers).
    INSERT INTO cob3_tenant.quota_counters AS q (tenant_id, organization_id, scope_kind, feature_id, window_key, consumed_quantity)
    VALUES (p_tenant_id, NULL, 'tenant_total', v_feature.feature_id, v_window, 0)
    ON CONFLICT ON CONSTRAINT quota_counters_bucket_uq DO NOTHING;
    SELECT q.consumed_quantity INTO v_tenant_used FROM cob3_tenant.quota_counters q
     WHERE q.tenant_id = p_tenant_id AND q.feature_id = v_feature.feature_id AND q.window_key = v_window
       AND q.scope_kind = 'tenant_total' AND q.organization_id IS NULL
       FOR UPDATE;
    IF v_org IS NOT NULL THEN
        INSERT INTO cob3_tenant.quota_counters AS q (tenant_id, organization_id, scope_kind, feature_id, window_key, consumed_quantity)
        VALUES (p_tenant_id, v_org, 'organization', v_feature.feature_id, v_window, 0)
        ON CONFLICT ON CONSTRAINT quota_counters_bucket_uq DO NOTHING;
        SELECT q.consumed_quantity INTO v_org_used FROM cob3_tenant.quota_counters q
         WHERE q.tenant_id = p_tenant_id AND q.feature_id = v_feature.feature_id AND q.window_key = v_window
           AND q.scope_kind = 'organization' AND q.organization_id = v_org
           FOR UPDATE;
    END IF;
--
    -- Idempotent insert; validation trigger enforces correction rules.
    INSERT INTO cob3_tenant.usage_events AS u
           (tenant_id, organization_id, feature_id, source_code, source_event_id, occurred_at,
            quantity, correction_of_event_id, request_id, created_by, updated_by)
    VALUES (p_tenant_id, v_org, v_feature.feature_id, p_source_code, p_source_event_id, p_occurred_at,
            p_quantity, p_correction_of_event_id, p_request_id,
            COALESCE(cob3_identity.ctx_actor(), 'system:usage'), COALESCE(cob3_identity.ctx_actor(), 'system:usage'))
    ON CONFLICT ON CONSTRAINT usage_events_idempotency_uq DO NOTHING
    RETURNING u.usage_event_id INTO v_new_id;
--
    IF v_new_id IS NULL THEN
        SELECT e.* INTO v_existing FROM cob3_tenant.usage_events e
         WHERE e.tenant_id = p_tenant_id AND e.source_code = p_source_code AND e.source_event_id = p_source_event_id;
        IF v_existing.feature_id = v_feature.feature_id
           AND v_existing.organization_id IS NOT DISTINCT FROM v_org
           AND v_existing.occurred_at = p_occurred_at
           AND v_existing.quantity = p_quantity
           AND v_existing.correction_of_event_id IS NOT DISTINCT FROM p_correction_of_event_id THEN
            usage_event_id := v_existing.usage_event_id;
            duplicate := true;
            RETURN;
        END IF;
        RAISE EXCEPTION USING ERRCODE = 'SKIDM',
            MESSAGE = pg_catalog.format('Usage idempotency key (%s, %s) was already used with a different payload.', p_source_code, p_source_event_id);
    END IF;
--
    IF p_enforce_limit AND p_quantity > 0 THEN
        IF NOT v_e.is_enabled THEN
            RAISE EXCEPTION USING ERRCODE = 'SKQTA',
                MESSAGE = pg_catalog.format('Feature %s is not entitled for this tenant (%s).', p_feature_code, v_e.source);
        END IF;
        IF NOT v_e.is_unlimited AND v_tenant_used + p_quantity > v_e.limit_value THEN
            RAISE EXCEPTION USING ERRCODE = 'SKQTA',
                MESSAGE = pg_catalog.format('Quota %s exceeded for window %s: %s used + %s requested > limit %s.',
                            p_feature_code, v_window, v_tenant_used, p_quantity, v_e.limit_value);
        END IF;
        SELECT EXISTS (SELECT 1 FROM cob3_tenant.organization_quota_allocations a
                        WHERE a.tenant_id = p_tenant_id AND a.feature_id = v_feature.feature_id AND a.status = 'active'
                          AND a.valid_from <= v_at AND a.valid_until > v_at)
          INTO v_has_allocs;
        IF v_has_allocs AND v_org IS NOT NULL THEN
            SELECT a.allocated_limit INTO v_alloc FROM cob3_tenant.organization_quota_allocations a
             WHERE a.tenant_id = p_tenant_id AND a.organization_id = v_org AND a.feature_id = v_feature.feature_id
               AND a.status = 'active' AND a.valid_from <= v_at AND a.valid_until > v_at;
            IF v_alloc IS NULL OR COALESCE(v_org_used, 0) + p_quantity > v_alloc THEN
                RAISE EXCEPTION USING ERRCODE = 'SKQTA',
                    MESSAGE = pg_catalog.format('Organization quota %s exceeded for window %s (allocation %s).',
                                p_feature_code, v_window, COALESCE(v_alloc::text, 'none'));
            END IF;
        END IF;
    END IF;
--
    UPDATE cob3_tenant.quota_counters q
       SET consumed_quantity = q.consumed_quantity + p_quantity, updated_at = pg_catalog.now()
     WHERE q.tenant_id = p_tenant_id AND q.feature_id = v_feature.feature_id AND q.window_key = v_window
       AND ((q.scope_kind = 'tenant_total' AND q.organization_id IS NULL)
            OR (v_org IS NOT NULL AND q.scope_kind = 'organization' AND q.organization_id = v_org));
    usage_event_id := v_new_id;
    RETURN;
END
$fn$;
--
-- Runtime entry point: tenant from authenticated context; organization
-- attribution must be the context organization (or none).
CREATE FUNCTION cob3_tenant.record_usage_event(
        p_feature_code text, p_source_code text, p_source_event_id text, p_occurred_at timestamptz,
        p_quantity numeric, p_organization_id uuid DEFAULT NULL, p_request_id uuid DEFAULT NULL,
        p_correction_of_event_id uuid DEFAULT NULL, p_enforce_limit boolean DEFAULT true,
        OUT usage_event_id uuid, OUT duplicate boolean)
    LANGUAGE plpgsql VOLATILE SECURITY DEFINER
    SET search_path = pg_catalog, pg_temp
AS $fn$
BEGIN
    IF NOT cob3_identity.ctx_auth_valid() THEN
        RAISE EXCEPTION USING ERRCODE = 'SKCTX', MESSAGE = 'No valid authenticated request context.';
    END IF;
    IF p_organization_id IS NOT NULL AND p_organization_id IS DISTINCT FROM cob3_identity.ctx_organization_id() THEN
        RAISE EXCEPTION USING ERRCODE = 'SKAUZ', MESSAGE = 'Usage may only be attributed to the request organization.';
    END IF;
    SELECT r.usage_event_id, r.duplicate INTO usage_event_id, duplicate
      FROM cob3_tenant.record_usage_internal(cob3_identity.ctx_tenant_id(), p_organization_id, p_feature_code, p_source_code,
                                             p_source_event_id, p_occurred_at, p_quantity, p_request_id,
                                             p_correction_of_event_id, p_enforce_limit) AS r;
END
$fn$;
--
-- Platform metering pipeline entry point (commercial role).
CREATE FUNCTION cob3_tenant.record_platform_usage_event(
        p_tenant_id uuid, p_feature_code text, p_source_code text, p_source_event_id text, p_occurred_at timestamptz,
        p_quantity numeric, p_organization_id uuid DEFAULT NULL, p_request_id uuid DEFAULT NULL,
        p_correction_of_event_id uuid DEFAULT NULL, p_enforce_limit boolean DEFAULT false,
        OUT usage_event_id uuid, OUT duplicate boolean)
    LANGUAGE sql VOLATILE SECURITY DEFINER
    SET search_path = pg_catalog, pg_temp
AS $fn$
    SELECT r.usage_event_id, r.duplicate
      FROM cob3_tenant.record_usage_internal(p_tenant_id, p_organization_id, p_feature_code, p_source_code,
                                             p_source_event_id, p_occurred_at, p_quantity, p_request_id,
                                             p_correction_of_event_id, p_enforce_limit) AS r
$fn$;
--
-- ---------------------------------------------------------------------------
-- Tenant lifecycle routines (provisioning role)
-- ---------------------------------------------------------------------------
CREATE FUNCTION cob3_tenant.use_system_actor(p_actor text)
    RETURNS void
    LANGUAGE plpgsql VOLATILE
    SET search_path = pg_catalog, pg_temp
AS $fn$
BEGIN
    IF p_actor IS NULL OR p_actor !~ '^system:[a-z0-9][a-z0-9_.:-]{0,200}$' THEN
        RAISE EXCEPTION USING ERRCODE = 'SKCTX', MESSAGE = 'Actor must match system:<lowercase-name>.';
    END IF;
    PERFORM pg_catalog.set_config('cob3.principal_id', '', true);
    PERFORM pg_catalog.set_config('cob3.actor', p_actor, true);
END
$fn$;
--
CREATE FUNCTION cob3_tenant.create_tenant(
        p_tenant_code text, p_name text, p_legal_name text, p_home_region text,
        p_request_id uuid, p_reason text, p_actor text DEFAULT 'system:provisioning')
    RETURNS uuid
    LANGUAGE plpgsql VOLATILE SECURITY DEFINER
    SET search_path = pg_catalog, pg_temp
AS $fn$
DECLARE
    v_tenant uuid;
BEGIN
    PERFORM cob3_tenant.use_system_actor(p_actor);
    INSERT INTO cob3_tenant.tenants (tenant_code, name, legal_name, status, home_region, created_by, updated_by)
    VALUES (p_tenant_code, p_name, p_legal_name, 'provisioning', p_home_region, p_actor, p_actor)
    RETURNING tenant_id INTO v_tenant;
    INSERT INTO cob3_tenant.tenant_lifecycle_events
           (tenant_id, from_status, to_status, occurred_at, reason, request_id, created_by, updated_by)
    VALUES (v_tenant, NULL, 'provisioning', pg_catalog.now(), p_reason, p_request_id, p_actor, p_actor);
    RETURN v_tenant;
END
$fn$;
--
CREATE FUNCTION cob3_tenant.transition_tenant_status(
        p_tenant_id uuid, p_to_status text, p_reason text, p_request_id uuid,
        p_actor text DEFAULT 'system:provisioning', p_suspension_reason text DEFAULT NULL,
        p_actor_principal_id uuid DEFAULT NULL)
    RETURNS text
    LANGUAGE plpgsql VOLATILE SECURITY DEFINER
    SET search_path = pg_catalog, pg_temp
AS $fn$
DECLARE
    v_from     text;
    v_existing cob3_tenant.tenant_lifecycle_events%ROWTYPE;
BEGIN
    PERFORM cob3_tenant.use_system_actor(p_actor);
    SELECT e.* INTO v_existing FROM cob3_tenant.tenant_lifecycle_events e
     WHERE e.tenant_id = p_tenant_id AND e.request_id = p_request_id;
    IF v_existing.tenant_lifecycle_event_id IS NOT NULL THEN
        IF v_existing.to_status = p_to_status THEN
            RETURN 'duplicate_request';
        END IF;
        RAISE EXCEPTION USING ERRCODE = 'SKIDM', MESSAGE = 'Lifecycle request_id was already used for a different transition.';
    END IF;
    SELECT t.status INTO v_from FROM cob3_tenant.tenants t WHERE t.tenant_id = p_tenant_id FOR UPDATE;
    IF v_from IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = 'SKINV', MESSAGE = 'Unknown tenant.';
    END IF;
    UPDATE cob3_tenant.tenants t
       SET status = p_to_status,
           suspension_reason = CASE WHEN p_to_status = 'suspended' THEN p_suspension_reason ELSE NULL END,
           updated_by = p_actor
     WHERE t.tenant_id = p_tenant_id;
    INSERT INTO cob3_tenant.tenant_lifecycle_events
           (tenant_id, from_status, to_status, occurred_at, reason, request_id, actor_principal_id, created_by, updated_by)
    VALUES (p_tenant_id, v_from, p_to_status, pg_catalog.now(), p_reason, p_request_id, p_actor_principal_id, p_actor, p_actor);
    RETURN 'transitioned';
END
$fn$;
--
-- Provisioning job queue (competing workers; SKIP LOCKED + lease).
CREATE FUNCTION cob3_tenant.claim_provisioning_job(p_job_types text[], p_lease interval DEFAULT interval '5 minutes',
                                                   p_actor text DEFAULT 'system:provisioning-worker')
    RETURNS SETOF cob3_tenant.provisioning_jobs
    LANGUAGE plpgsql VOLATILE SECURITY DEFINER
    SET search_path = pg_catalog, pg_temp
AS $fn$
BEGIN
    PERFORM cob3_tenant.use_system_actor(p_actor);
    RETURN QUERY
    UPDATE cob3_tenant.provisioning_jobs j
       SET status = 'running', started_at = pg_catalog.now(), lease_expires_at = pg_catalog.now() + p_lease,
           attempt_count = j.attempt_count + 1, completed_at = NULL, updated_by = p_actor
     WHERE j.provisioning_job_id = (
           SELECT c.provisioning_job_id
             FROM cob3_tenant.provisioning_jobs c
            WHERE c.job_type = ANY (p_job_types)
              AND c.status = 'pending'
              AND (c.next_attempt_at IS NULL OR c.next_attempt_at <= pg_catalog.now())
            ORDER BY c.next_attempt_at NULLS FIRST, c.created_at
            LIMIT 1
              FOR UPDATE SKIP LOCKED)
    RETURNING j.*;
END
$fn$;
--
-- Idempotent provider event intake; duplicates are no-ops only when the
-- payload digest matches. Tenant must already have been resolved from a
-- trusted provider-customer mapping by the caller (never from webhook data).
CREATE FUNCTION cob3_tenant.record_provider_event(
        p_tenant_id uuid, p_provider_code text, p_provider_account_reference text, p_external_event_id text,
        p_event_type text, p_occurred_at timestamptz, p_payload_digest bytea,
        p_actor text DEFAULT 'system:billing-ingress',
        OUT provider_event_id uuid, OUT duplicate boolean)
    LANGUAGE plpgsql VOLATILE SECURITY DEFINER
    SET search_path = pg_catalog, pg_temp
AS $fn$
#variable_conflict use_column
DECLARE
    v_existing cob3_tenant.provider_events%ROWTYPE;
    v_id       uuid;
BEGIN
    PERFORM cob3_tenant.use_system_actor(p_actor);
    duplicate := false;
    IF NOT EXISTS (SELECT 1 FROM cob3_tenant.billing_accounts b
                    WHERE b.tenant_id = p_tenant_id AND b.provider_code = p_provider_code
                      AND b.provider_account_reference = p_provider_account_reference) THEN
        RAISE EXCEPTION USING ERRCODE = 'SKAUZ',
            MESSAGE = 'Provider account is not mapped to this tenant through a billing account; route to the restricted platform ingress queue.';
    END IF;
    INSERT INTO cob3_tenant.provider_events AS e
           (tenant_id, provider_code, provider_account_reference, external_event_id, event_type, occurred_at,
            payload_digest, created_by, updated_by)
    VALUES (p_tenant_id, p_provider_code, p_provider_account_reference, p_external_event_id, p_event_type, p_occurred_at,
            p_payload_digest, p_actor, p_actor)
    ON CONFLICT ON CONSTRAINT provider_events_external_uq DO NOTHING
    RETURNING e.provider_event_id INTO v_id;
    IF v_id IS NOT NULL THEN
        provider_event_id := v_id;
        RETURN;
    END IF;
    SELECT e.* INTO v_existing FROM cob3_tenant.provider_events e
     WHERE e.provider_code = p_provider_code AND e.provider_account_reference = p_provider_account_reference
       AND e.external_event_id = p_external_event_id;
    IF v_existing.tenant_id = p_tenant_id AND v_existing.payload_digest = p_payload_digest
       AND v_existing.event_type = p_event_type THEN
        provider_event_id := v_existing.provider_event_id;
        duplicate := true;
        RETURN;
    END IF;
    RAISE EXCEPTION USING ERRCODE = 'SKIDM',
        MESSAGE = 'Provider event id was already recorded with different content; route to reconciliation.';
END
$fn$;
--
-- ===========================================================================
-- Tenant-table triggers
-- ===========================================================================
--
-- tenants -------------------------------------------------------------------
CREATE FUNCTION cob3_tenant.tg_tenants_lifecycle()
    RETURNS trigger
    LANGUAGE plpgsql
    SET search_path = pg_catalog, pg_temp
AS $fn$
BEGIN
    IF TG_OP = 'UPDATE' THEN
        IF NEW.status IS DISTINCT FROM OLD.status THEN
            IF NEW.status = 'active' THEN
                NEW.activated_at := COALESCE(OLD.activated_at, pg_catalog.now());
            END IF;
            IF NEW.status = 'suspended' THEN
                NEW.suspended_at := pg_catalog.now();
            ELSE
                NEW.suspended_at := NULL;
                NEW.suspension_reason := NULL;
            END IF;
            IF NEW.status = 'closed' THEN
                NEW.closed_at := pg_catalog.now();
            END IF;
        END IF;
        IF OLD.activated_at IS NOT NULL AND NEW.activated_at IS DISTINCT FROM OLD.activated_at THEN
            RAISE EXCEPTION USING ERRCODE = 'SKIMM', MESSAGE = 'tenants.activated_at records first activation and is immutable.';
        END IF;
    END IF;
    RETURN NEW;
END
$fn$;
CREATE TRIGGER trg_10_state BEFORE INSERT OR UPDATE OF status ON cob3_tenant.tenants
    FOR EACH ROW EXECUTE FUNCTION cob3_identity.tg_state_transition('status',
        '>provisioning', 'provisioning>active', 'provisioning>closed', 'active>suspended', 'active>closing',
        'suspended>active', 'suspended>closing', 'closing>closed', 'closing>active');
CREATE TRIGGER trg_20_immutable BEFORE UPDATE ON cob3_tenant.tenants
    FOR EACH ROW EXECUTE FUNCTION cob3_identity.tg_immutable_columns('tenant_code', 'home_region');
CREATE TRIGGER trg_30_lifecycle BEFORE INSERT OR UPDATE ON cob3_tenant.tenants
    FOR EACH ROW EXECUTE FUNCTION cob3_tenant.tg_tenants_lifecycle();
--
CREATE FUNCTION cob3_tenant.tg_tenants_lifecycle_recorded()
    RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path = pg_catalog, pg_temp
AS $fn$
BEGIN
    IF TG_OP = 'UPDATE' AND NEW.status IS NOT DISTINCT FROM OLD.status THEN
        RETURN NULL;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM cob3_tenant.tenant_lifecycle_events e
                    WHERE e.tenant_id = NEW.tenant_id AND e.to_status = NEW.status
                      AND e.created_at = pg_catalog.now()) THEN
        RAISE EXCEPTION USING ERRCODE = 'SKINV',
            MESSAGE = pg_catalog.format('Tenant status change to %s must be recorded in tenant_lifecycle_events in the same transaction.', NEW.status);
    END IF;
    RETURN NULL;
END
$fn$;
CREATE CONSTRAINT TRIGGER trg_80_lifecycle_recorded AFTER INSERT OR UPDATE OF status ON cob3_tenant.tenants
    DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION cob3_tenant.tg_tenants_lifecycle_recorded();
--
-- tenant_lifecycle_events -----------------------------------------------------
CREATE FUNCTION cob3_tenant.tg_lifecycle_events_validate()
    RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path = pg_catalog, pg_temp
AS $fn$
BEGIN
    IF NEW.from_status IS NULL AND EXISTS (SELECT 1 FROM cob3_tenant.tenant_lifecycle_events e WHERE e.tenant_id = NEW.tenant_id) THEN
        RAISE EXCEPTION USING ERRCODE = 'SKINV', MESSAGE = 'from_status may be NULL only for the tenant creation event.';
    END IF;
    IF NEW.from_status IS NOT NULL AND NOT EXISTS (SELECT 1 FROM cob3_tenant.tenant_lifecycle_events e WHERE e.tenant_id = NEW.tenant_id) THEN
        RAISE EXCEPTION USING ERRCODE = 'SKINV', MESSAGE = 'The first lifecycle event must be the creation event (from_status NULL).';
    END IF;
    RETURN NEW;
END
$fn$;
CREATE TRIGGER trg_10_validate BEFORE INSERT ON cob3_tenant.tenant_lifecycle_events
    FOR EACH ROW EXECUTE FUNCTION cob3_tenant.tg_lifecycle_events_validate();
--
-- provisioning_jobs ------------------------------------------------------------
CREATE TRIGGER trg_10_state BEFORE INSERT OR UPDATE OF status ON cob3_tenant.provisioning_jobs
    FOR EACH ROW EXECUTE FUNCTION cob3_identity.tg_state_transition('status',
        '>pending', 'pending>running', 'pending>failed', 'running>succeeded', 'running>failed', 'running>pending', 'failed>pending');
CREATE TRIGGER trg_20_immutable BEFORE UPDATE ON cob3_tenant.provisioning_jobs
    FOR EACH ROW EXECUTE FUNCTION cob3_identity.tg_immutable_columns('job_type', 'idempotency_key');
CREATE TRIGGER trg_21_nondecreasing BEFORE UPDATE ON cob3_tenant.provisioning_jobs
